// Keys are generated by the server, but check anyway so a bad key can never
// reach outside the uploads directory (e.g. "../../etc/passwd") or name an
// unexpected object in a remote store.
const SAFE_KEY = /^[a-z0-9-]+(\/[a-z0-9-]+)*\.[a-z0-9]+$/;

export const assertSafeStorageKey = (key: string): void => {
  if (!SAFE_KEY.test(key)) {
    throw new Error(`Unsafe storage key: ${key}`);
  }
};

/**
 * Where uploaded files live. The app only talks to this interface, so moving
 * from local disk to object storage means adding one implementation and
 * changing configuration (STORAGE_DRIVER); nothing else changes. Implemented:
 * local disk and Cloudinary.
 */
export type FileStorage = {
  /** Stores `data` under `key` (e.g. "pets/3f2a….jpg"). */
  save: (key: string, data: Buffer, contentType: string) => Promise<void>;
  /** Removes the file; a missing file is not an error. */
  delete: (key: string) => Promise<void>;
  /** The URL browsers use to load the file. */
  publicUrl: (key: string) => string;
};
